import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m = int(data[0])
    n = int(data[1])
    if m <= 0 or n <= 0:
        return
    lines = []
    for j in range(n):
        row = [str(i * j) for i in range(m)]
        lines.append(' '.join(row))
    sys.stdout.write('\n'.join(lines))

if __name__ == "__main__":
    main()
